// Synthetic replica of expo-image@2 sources (TSX). The published package ships
// the precompiled build/ output; this src mirrors it for fidelity.
import { requireNativeViewManager } from "expo-modules-core";

const ImageNativeView = requireNativeViewManager("ExpoImage");

export const EXPO_IMAGE_OK = "EXPO_IMAGE_OK";

export type ImageSource = { uri: string };

export function Image(props: { source: ImageSource; contentFit?: string }) {
  return <ImageNativeView source={props.source} contentFit={props.contentFit ?? "cover"} />;
}

export function prefetch(urls: string | string[]): Promise<boolean> {
  return Promise.resolve(Array.isArray(urls) ? urls.length > 0 : Boolean(urls));
}
